            )
        except RuntimeError as exc:
            raise HTTPException(409, str(exc)) from exc
        except ValueError as exc:
            raise HTTPException(422, str(exc)) from exc

        async def updates():
            previous: str | None = None
            while True:
                current = coordinator.get(run.run_id)
                if current is None:
                    yield json.dumps(
